diff --git a/web/src/lib/AdminForm.svelte b/web/src/lib/AdminForm.svelte
index cd1a9d5..bc28c7f 100644
--- a/web/src/lib/AdminForm.svelte
+++ b/web/src/lib/AdminForm.svelte
@@ -19,6 +19,8 @@
  function observe(next:AdminSnapshot|null,replace=false,background=false){
   if(base&&next){const order=compareAdminObservation(base,next);if(order==='OLDER')return false;if(order==='CONFLICT'){blockConflict();return false;}}
   if(conflicted&&background)return false;conflicted=false;
+  // A confirmation belongs to the observed source, even with no dirty fields.
+  if(base&&next&&!sameObservation(base,next)&&candidate){candidate=null;dialog?.close();message='Dữ liệu thay đổi trong lúc xác nhận. Hãy xem lại trước khi gửi.';}
   if(base&&next&&!sameObservation(base,next)&&dirty&&!replace){latest=next;candidate=null;dialog?.close();if(!unresolved)message='Dữ liệu đã thay đổi. Phần bạn nhập vẫn được giữ; xem bản mới trước khi lưu.';return false;}
   if(next){if(replace||!dirty)draft=formOf(next);base=next;}latest=null;return true;
  }
